Another useful property of C++ is that it allows for function overloading. That is, it
allows for two or more functions to have the same name provided only that their argument
types di ff er. The code below illustrates this with a modification of the square program.
squareOverload . cpp
< iostream >
std ;
square ( x );
square ( x );
main (){
x ;
cout << " Enter a number " ;
cin >> x ;
cout << square ( x ) << endl ;
y ;
cout << " Enter an integer " ;
cin >> y ;
cout << square ( y ) << endl ;
0;
}
square ( x ){
cout << " From double version " << endl ;
x x ;
}
square ( x ){
cout << " From int version " << endl ;
x x ;
}
